classDiagram
    class Member {
        +memberId
        +name
        +searchCatalogue()
        +borrowBook()
        +returnBook()
        +renewLoan()
    }
    class Librarian {
        +librarianId
        +manageBooks()
        +manageMembers()
        +manageLoans()
        +collectFines()
    }
    class Book {
        +ISBN
        +title
        +author
        +available
    }
    class Loan {
        +loanId
        +dueDate
        +isOverdue()
    }
    class Catalogue {
        +search()
    }
    class EmailService {
        +sendReminder()
    }
    Member "1" --> "*" Loan : borrows
    Loan "*" --> "1" Book : contains
    Librarian "1" --> "*" Book : manages
    Librarian "1" --> "*" Member : manages
    Librarian "1" --> "*" Loan : manages
    Loan "*" --> EmailService : triggers
    EmailService --> Member : notifies

